#' Categorical Bars (Core, Python)
#'
#' 
#' @param data .
#' @param dep .
#' @param group .
#' @param counts .
#' @param subject .
#' @param resultssubtitle .
#' @param showCells .
#' @param showCases .
#' @param showPlot .
#' @param barScale .
#' @param label .
#' @param digitsperc .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$missing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$groups} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cells} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$dropped} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$association} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$pearson} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$effects} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$barPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyjjbarstats <- function(
    data,
    dep = NULL,
    group = NULL,
    counts = NULL,
    subject = NULL,
    resultssubtitle = FALSE,
    showCells = TRUE,
    showCases = FALSE,
    showPlot = TRUE,
    barScale = "percentage",
    label = "percentage",
    digitsperc = 0,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyjjbarstats requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(group)) group <- jmvcore::resolveQuo(jmvcore::enquo(group))
    if ( ! missing(counts)) counts <- jmvcore::resolveQuo(jmvcore::enquo(counts))
    if ( ! missing(subject)) subject <- jmvcore::resolveQuo(jmvcore::enquo(subject))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(group), group, NULL),
            `if`( ! missing(counts), counts, NULL),
            `if`( ! missing(subject), subject, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in group) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyjjbarstatsOptions$new(
        dep = dep,
        group = group,
        counts = counts,
        subject = subject,
        resultssubtitle = resultssubtitle,
        showCells = showCells,
        showCases = showCases,
        showPlot = showPlot,
        barScale = barScale,
        label = label,
        digitsperc = digitsperc,
        showConsole = showConsole)

    analysis <- pyjjbarstatsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

